public final class FireflyRushSkillGameTests {
    private static final String BATCH="dreamseekers_firefly_rush",PREFIX="RushGT_";
    private static final UUID PERMANENT_MOVE=UUID.fromString("f6c2c11d-945c-45cc-84be-e93d3f66e801"),PERMANENT_FLY=UUID.fromString("f6c2c11d-945c-45cc-84be-e93d3f66e802");
    private static final List<Entity> ENTITIES=new ArrayList<>();private static final Set<String> ACCOUNTS=new LinkedHashSet<>();private static final Map<String,FakePlayer> PLAYERS=new HashMap<>();
    @AfterBatch(batch=BATCH) public static void cleanup(ServerLevel level){for(Entity e:List.copyOf(ENTITIES))if(!e.isRemoved()){if(e instanceof ServerPlayer p)p.serverLevel().removePlayerImmediately(p,Entity.RemovalReason.DISCARDED);else e.discard();}BuildingServerEvents.getBuildings().removeIf(b->ACCOUNTS.contains(b.ownerName));PlayerServerEvents.players.removeIf(p->ACCOUNTS.contains(p.getGameProfile().getName()));PlayerServerEvents.rtsPlayers.removeIf(p->ACCOUNTS.contains(p.name));ResourcesServerEvents.resourcesList.removeIf(r->ACCOUNTS.contains(r.ownerName));for(var c:FORCED)level.setChunkForced(c.x,c.z,false);FORCED.clear();ENTITIES.clear();ACCOUNTS.clear();PLAYERS.clear();}

    @GameTest(template="unit_isolation_arena",batch=BATCH,timeoutTicks=860)
    public static void actualSenderSelfTokenReplayAndLegacyWorkerRemainAuthoritative(GameTestHelper h){
        arena(h,24,8,24);var worker=worker(h,"Auth",4,1,5);var other=worker(h,"Other",4,1,15);var stone=DreamseekersMod.STONE_SPIRIT_WORKER.get().create(h.getLevel());stone.setOwnerName(account("Auth"));stone.setNoAi(true);place(h,stone,10,1,5);var owner=player(h,"Auth");var foreign=player(h,"Other");
        ready(h,worker,other,stone,owner,foreign).thenExecute(()->{var input=request(worker);var original=new SkillNetwork.Cast(input);FriendlyByteBuf wire=new FriendlyByteBuf(Unpooled.buffer());SkillNetwork.Cast decoded;try{original.encode(wire);decoded=SkillNetwork.Cast.decode(wire);h.assertTrue(decoded.equals(original)&&wire.readableBytes()==0,"actual self-skill packet codec preserves exact tokens without trailing input");}finally{wire.release();}require(h,decoded.execute(null),SkillResult.INVALID_REQUEST,"missing real sender");require(h,decoded.execute(foreign),SkillResult.NOT_OWNER,"foreign player cannot control owned worker");require(h,SkillService.request(owner,new SkillRequest(UnitSkill.FIREFLY_RUSH,worker.getId(),UUID.randomUUID(),input.revision(),worker.getId(),worker.getUUID())),SkillResult.INVALID_SOURCE,"source UUID substitution");require(h,SkillService.request(owner,new SkillRequest(UnitSkill.FIREFLY_RUSH,worker.getId(),worker.getUUID(),input.revision(),other.getId(),other.getUUID())),SkillResult.INVALID_TARGET,"personal ability cannot target another unit");require(h,java.util.concurrent.CompletableFuture.supplyAsync(()->decoded.execute(owner)).join(),SkillResult.INVALID_REQUEST,"off-thread skill request fails closed");require(h,SkillService.request(owner,new SkillRequest(UnitSkill.FIREFLY_RUSH,stone.getId(),stone.getUUID(),stone.rts().skills().revision(),stone.getId(),stone.getUUID())),SkillResult.INVALID_SOURCE,"legacy stone worker gains no new active skill");h.assertTrue(stone.getAbilities().isEmpty()&&worker.getAbilities().get().equals(List.of(UnitSkillAbility.FIREFLY_RUSH,com.dreamseekers.neutralcontract.ContractAbility.INSTANCE))&&cd(worker)==0&&!FireflyRush.active(worker),"denials keep legacy abilities and personal cooldown unchanged");int capacity=worker.getMaxResources();h.assertTrue(!com.solegendary.reignofnether.research.ResearchServerEvents.playerHasResearch(worker.getOwnerName(),com.solegendary.reignofnether.building.production.ProductionItems.RESEARCH_RESOURCE_CAPACITY),"fixture has no unlocked carrying research");require(h,decoded.execute(owner),SkillResult.SUCCESS,"real owner activates self rush");require(h,decoded.execute(owner),SkillResult.REPLAY,"same successful input cannot replay");require(h,cast(h,worker),SkillResult.COOLDOWN,"fresh duplicate cannot refresh duration");h.assertTrue(FireflyRush.remainingTicks(worker)==100&&cd(worker)==500&&worker.getMaxResources()==capacity,"server owns exact duration/cooldown and never grants carrying capacity");stableBank(h,"Auth");stableBank(h,"Other");pass("AUTHORITY_SELF_TOKEN_REPLAY_STONE_UNCHANGED");}).thenSucceed();
    }

    @GameTest(template="unit_isolation_arena",batch=BATCH,timeoutTicks=900)
    public static void idleRushCreatesNoHomeOrderPathOrTeleportAndExpiresWithoutRefund(GameTestHelper h){
        arena(h,24,8,24);var worker=worker(h,"Idle",5,1,10);var control=worker(h,"Idle",5,1,16);Vec3[] start=new Vec3[2];long[] at={0};
        ready(h,worker,control).thenExecute(()->{worker.setNoAi(false);control.setNoAi(false);start[0]=worker.position();start[1]=control.position();
            // Native EntityJoin gives each Unit a random horizontal nudge. Match the untouched
            // source's actual residual velocity in a real uncast control; do not clear inertia.
            control.setDeltaMovement(worker.getDeltaMovement());h.assertTrue(worker.getDeltaMovement().horizontalDistanceSqr()>0&&control.getDeltaMovement().equals(worker.getDeltaMovement()),"matched declared control starts with actual nonzero native Join inertia");System.out.println("FIREFLY_RUSH_IDLE_INITIAL pos="+worker.position()+" controlPos="+control.position()+" velocity="+worker.getDeltaMovement()+" controlVelocity="+control.getDeltaMovement()+" noGravity="+worker.isNoGravity()+" onGround="+worker.onGround()+" "+rawRushState(worker));at[0]=h.getLevel().getGameTime();require(h,cast(h,worker),SkillResult.SUCCESS,"idle personal activation");h.assertTrue(worker.getMoveGoal().getMoveTarget()==null&&worker.getNavigation().isDone()&&worker.getReturnResourcesGoal().getBuildingTarget()==null&&!FireflyRush.hasPausedWork(worker),"idle rush creates no home destination, return task or hidden work");})
          .thenIdle(99).thenExecute(()->{System.out.println("FIREFLY_RUSH_IDLE_DIAGNOSTIC initial="+start[0]+" now="+worker.position()+" delta="+worker.position().subtract(start[0])+" controlDelta="+control.position().subtract(start[1])+" velocity="+worker.getDeltaMovement()+" noGravity="+worker.isNoGravity()+" onGround="+worker.onGround()+" active="+FireflyRush.active(worker)+" cd="+cd(worker)+" anchor="+worker.getAnchor()+" "+rawRushState(worker));h.assertTrue(FireflyRush.active(worker)&&FireflyRush.remainingTicks(worker)==1&&h.getLevel().getGameTime()-at[0]==99,"actual hundred-tick lifetime has not expired early");idleDriftMatch(h,worker,control,start,"ninety-nine actual ticks preserve only matched native inertia, never synthesize travel or teleport");})
          .thenIdle(2).thenExecute(()->{h.assertTrue(!FireflyRush.active(worker)&&FireflyRush.remainingTicks(worker)==0&&cd(worker)==399,"normal expiration clears only personal effect, not paid cooldown");close(h,SkillEffects.bonus(worker,BuffKind.MOVEMENT_SPEED),0,"no permanent rush buff remains");idleDriftMatch(h,worker,control,start,"expiration does not invent an old destination or change native idle drift");stableBank(h,"Idle");pass("IDLE_NO_HOME_PATH_TELEPORT_EXACT_EXPIRY");}).thenSucceed();
    }

    @GameTest(template="unit_isolation_arena",batch=BATCH,timeoutTicks=1150)
    public static void actualFlightUsesPersonal35OverRealTide10AndRestoresPermanentAttributes(GameTestHelper h){
        arena(h,24,8,24);var normal=worker(h,"Speed",4,1,6);var fast=worker(h,"Speed",4,1,16);var jelly=DreamseekersMod.JELLYFISH_UNIT.get().create(h.getLevel());jelly.setOwnerName(account("Speed"));jelly.setNoAi(true);place(h,jelly,4,2,13);double[] originalMove=new double[2],originalFly=new double[2];Vec3[] start=new Vec3[2];
        ready(h,normal,fast,jelly).thenExecute(()->{for(int i=0;i<2;i++){var w=i==0?normal:fast;w.getAttribute(Attributes.MOVEMENT_SPEED).addPermanentModifier(new AttributeModifier(PERMANENT_MOVE,"real permanent movement fixture",.025,AttributeModifier.Operation.ADDITION));w.getAttribute(Attributes.FLYING_SPEED).addPermanentModifier(new AttributeModifier(PERMANENT_FLY,"real permanent flight fixture",.025,AttributeModifier.Operation.ADDITION));originalMove[i]=w.getAttributeValue(Attributes.MOVEMENT_SPEED);originalFly[i]=w.getAttributeValue(Attributes.FLYING_SPEED);}fast.setHealth(fast.getMaxHealth()-2);require(h,SkillService.request(player(h,"Speed"),new SkillRequest(UnitSkill.JELLY_FLOW,jelly.getId(),jelly.getUUID(),jelly.rts().skills().revision(),fast.getId(),fast.getUUID())),SkillResult.SUCCESS,"real jelly healing creates later ordinary tide buff, not a trusted fabricated research provider");})
          .thenIdle(70).thenExecute(()->{normal.setNoAi(false);fast.setNoAi(false);order(h,normal,UnitAction.MOVE,pos(h,20,0,6));order(h,fast,UnitAction.MOVE,pos(h,20,0,16));})
          .thenWaitUntil(()->{movedOrder(h,normal);movedOrder(h,fast);})
          .thenExecute(()->{start[0]=normal.position();start[1]=fast.position();require(h,cast(h,fast),SkillResult.SUCCESS,"rush preserves already accepted non-work MOVE");h.assertTrue(fast.getMoveGoal().getMoveTarget()!=null&&!FireflyRush.hasPausedWork(fast),"existing non-work movement is not stopped or relabelled work");close(h,fast.getAttributeValue(Attributes.MOVEMENT_SPEED),originalMove[1]*1.35,"real ground attribute consumes exactly personal35");close(h,fast.getAttributeValue(Attributes.FLYING_SPEED),originalFly[1]*1.35,"real flight controller attribute consumes exactly personal35");})
          .thenIdle(30).thenExecute(()->{double plain=normal.position().distanceTo(start[0]),quick=fast.position().distanceTo(start[1]);System.out.println("FIREFLY_RUSH_ACTUAL_FLIGHT normal="+plain+" rush="+quick+" normalPos="+normal.position()+" rushPos="+fast.position());h.assertTrue(plain>.5&&quick>plain*1.15&&quick<plain*1.6,"genuine matched FlyingMoveControl navigation travels farther during same real thirty ticks, not just attribute display");h.assertTrue(h.getLevel().noCollision(normal)&&h.getLevel().noCollision(fast)&&fast.getNavigation() instanceof LowAltitudeFlyingNavigation&&!fast.noPhysics,"ordinary low collision flight remains real");h.assertTrue(normal.position().distanceTo(Vec3.atBottomCenterOf(pos(h,20,1,6)))>4&&fast.position().distanceTo(Vec3.atBottomCenterOf(pos(h,20,1,16)))>4,"both real flight probes are explicitly still before destination slowdown");order(h,normal,UnitAction.STOP,BlockPos.ZERO);order(h,fast,UnitAction.STOP,BlockPos.ZERO);})
          .thenIdle(30).thenExecute(()->{h.assertTrue(jelly.distanceToSqr(fast)<=144,"actual completed-heal source/target remain within twelve blocks, not a fabricated tide provider");h.assertTrue(SkillEffects.hasNamedBuff(fast,"light_tide",BuffKind.MOVEMENT_SPEED),"real completed jelly provides overlapping ordinary ten-percent tide");close(h,SkillEffects.bonus(fast,BuffKind.MOVEMENT_SPEED),.35,"personal35 and real ordinary10 take max, never add/multiply twice");})
          .thenIdle(41).thenExecute(()->{h.assertTrue(!FireflyRush.active(fast)&&SkillEffects.hasNamedBuff(fast,"light_tide",BuffKind.MOVEMENT_SPEED),"personal100 expires while later actual tide remains");close(h,SkillEffects.bonus(fast,BuffKind.MOVEMENT_SPEED),.10,"expiration exposes still-live weaker ordinary contribution");close(h,fast.getAttributeValue(Attributes.FLYING_SPEED),originalFly[1]*1.10,"only ordinary10 remains on actual flying attribute");})
          .thenIdle(40).thenExecute(()->{close(h,fast.getAttributeValue(Attributes.MOVEMENT_SPEED),originalMove[1],"movement returns to real permanent baseline");close(h,fast.getAttributeValue(Attributes.FLYING_SPEED),originalFly[1],"flight returns to real permanent baseline");h.assertTrue(fast.getAttribute(Attributes.MOVEMENT_SPEED).getModifier(PERMANENT_MOVE)!=null&&fast.getAttribute(Attributes.FLYING_SPEED).getModifier(PERMANENT_FLY)!=null,"permanent modifiers were never removed or rewritten");stableBank(h,"Speed");pass("REAL_FLIGHT_MAX35_TIDE10_PERMANENT_RESTORE");}).thenSucceed();
    }

    @GameTest(template="unit_isolation_arena",batch=BATCH,timeoutTicks=1400)
    public static void realGatherCountdownAndHarvestPauseThenCurrentTaskNaturallyResumes(GameTestHelper h){
        arena(h,24,8,24);var w=worker(h,"Gather",6,1,10);BlockPos log=pos(h,9,2,10);h.getLevel().setBlock(log,Blocks.OAK_LOG.defaultBlockState(),3);int[] progress={0};Vec3[] at={null};
        ready(h,w).thenExecute(()->{h.assertTrue(ResourceSources.getBlockResourceName(log,h.getLevel())==ResourceName.WOOD,"actual native log is a valued work source");w.setNoAi(false);order(h,w,UnitAction.MOVE,log);})
          .thenWaitUntil(()->h.assertTrue(w.getGatherResourceGoal().isGathering()&&log.equals(w.getGatherResourceGoal().getGatherTarget())&&w.getGatherResourceGoal().getGatherTicksLeft()>0&&w.getGatherResourceGoal().data.targetResourceSource!=null&&w.getGatherResourceGoal().getGatherTicksLeft()<w.getGatherResourceGoal().data.targetResourceSource.ticksToGather,"real dispatched gathering actually progressed before interruption: "+FireflyNavigationTestDiagnostics.describe(w,bank(h,"Gather"))))
          .thenExecute(()->{progress[0]=w.getGatherResourceGoal().getGatherTicksLeft();at[0]=w.position();require(h,cast(h,w),SkillResult.SUCCESS,"rush interrupts actual gathering");h.assertTrue(FireflyRush.hasPausedWork(w)&&!w.getGatherResourceGoal().isGathering(),"actual current gather remains intent but cannot report active work");})
          .thenIdle(99).thenExecute(()->{h.assertTrue(FireflyRush.remainingTicks(w)==1&&w.getGatherResourceGoal().getGatherTicksLeft()==progress[0]&&log.equals(w.getGatherResourceGoal().getGatherTarget()),"both goal tick entry paths preserve exact countdown/current target during ninety-nine real ticks");h.assertTrue(h.getLevel().getBlockState(log).is(Blocks.OAK_LOG)&&w.getItems().isEmpty()&&w.position().distanceToSqr(at[0])<.04,"paused work neither harvests nor invents a work route");stableBank(h,"Gather");})
          .thenWaitUntil(()->h.assertTrue(!h.getLevel().getBlockState(log).is(Blocks.OAK_LOG)&&Resources.getTotalResourcesFromItems(w.getItems()).wood>0,"unchanged current task naturally completes an actual harvest after rush expires"))
          .thenExecute(()->{h.assertTrue(!FireflyRush.active(w)&&cd(w)>0,"completion is normal resumed work, not cooldown refund");stableBank(h,"Gather");pass("REAL_GATHER_COUNTDOWN_PAUSE_NATURAL_RESUME");}).thenSucceed();
    }

    @GameTest(template="work_isolation_arena",batch=BATCH,timeoutTicks=1800)
    public static void buildingOwnTickCannotAdvanceConstructionOrChargeNewRepairDuringRush(GameTestHelper h){
        arena(h,72,16,48);String owner=account("Building");var repair=install(h,DreamseekersMod.DREAM_DEPOT,pos(h,8,1,8),owner,true);var construction=install(h,DreamseekersMod.DREAM_DEPOT,pos(h,39,1,8),owner,false);repair.destroyRandomBlocks(24);var a=worker(h,"Building",5,1,12);var b=worker(h,"Building",36,1,12);int[] initial={0,0},paused={0,0},settled={0,0};float[] milliseconds=new float[2];int[] wood={0};
        ready(h,a,b).thenIdle(20).thenExecute(()->{repair.initPlacedBlocks();construction.initPlacedBlocks();initial[0]=repair.getBlocksPlaced();initial[1]=construction.getBlocksPlaced();h.assertTrue(repair.isBuilt&&!construction.isBuilt&&!repair.selfBuilding&&!construction.selfBuilding&&repair.blocksPerBuild==1&&repair.baseMsPerBuild==500,"real completed repair and unfinished foundation fixtures retain native worker queues/rates");h.assertTrue(repair.getBlocksTotal()-initial[0]>=24&&initial[1]>0,"actual damaged blocks and ordinary foundation are present");a.setNoAi(false);b.setNoAi(false);order(h,a,UnitAction.BUILD_REPAIR,repair.originPos);order(h,b,UnitAction.BUILD_REPAIR,construction.originPos);})
          .thenWaitUntil(()->h.assertTrue(repair.getBlocksPlaced()>initial[0]&&construction.getBlocksPlaced()>initial[1]&&bank(h,"Building").wood<5000&&a.getBuildRepairGoal().isBuilding()&&b.getBuildRepairGoal().isBuilding(),"both actual workers physically reach faces and real building ticks advance/charge before interruption"))
          .thenExecute(()->{h.assertTrue(repair.getBlocksPlaced()<repair.getBlocksTotal()&&construction.getBlocksPlaced()<construction.getBlocksTotal(),"both native jobs still contain real work to pause");require(h,cast(h,a),SkillResult.SUCCESS,"repair pause");require(h,cast(h,b),SkillResult.SUCCESS,"construction pause");wood[0]=bank(h,"Building").wood;paused[0]=repair.getBlocksPlaced();paused[1]=construction.getBlocksPlaced();milliseconds[0]=repair.msToNextBuild;milliseconds[1]=construction.msToNextBuild;h.assertTrue(repair.getBuilders().isEmpty()&&construction.getBuilders().isEmpty(),"actual building-side builder discovery excludes paused workers, not just goal tick");})
          // A block paid/queued before cast may settle. Do not erase/refund that native queue.
          .thenIdle(20).thenExecute(()->{settled[0]=repair.getBlocksPlaced();settled[1]=construction.getBlocksPlaced();h.assertTrue(settled[0]>=paused[0]&&settled[1]>=paused[1],"already committed native geometry is not rolled back");h.assertTrue(bank(h,"Building").wood==wood[0],"settling a prior paid block is not a new repair charge");})
          .thenIdle(79).thenExecute(()->{h.assertTrue(FireflyRush.remainingTicks(a)==1&&FireflyRush.remainingTicks(b)==1,"construction observation retains full original ninety-nine ticks");h.assertTrue(repair.getBlocksPlaced()==settled[0]&&construction.getBlocksPlaced()==settled[1],"actual structure geometry has no newly progressed worker blocks");h.assertTrue(repair.msToNextBuild==milliseconds[0]&&construction.msToNextBuild==milliseconds[1]&&bank(h,"Building").wood==wood[0],"building-own countdown and new repair debit stay exactly frozen");unchangedOtherResources(h,"Building");})
          .thenWaitUntil(()->h.assertTrue(repair.getBlocksPlaced()>settled[0]&&construction.getBlocksPlaced()>settled[1]&&bank(h,"Building").wood<wood[0],"current native construction and paid repair resume after expiration without a restored task snapshot"))
          .thenExecute(()->{h.assertTrue(a.getBuildRepairGoal().getBuildingTarget()==repair&&b.getBuildRepairGoal().getBuildingTarget()==construction,"same legitimate current placements remain authoritative");pass("BUILDING_OWN_TICK_CONSTRUCTION_REPAIR_PAUSE");}).thenSucceed();
    }

    @GameTest(template="work_isolation_arena",batch=BATCH,timeoutTicks=1200)
    public static void actualAtStockpileDepositAndValuedPickupPauseWithoutCargoOrBankDuplication(GameTestHelper h){
        arena(h,72,16,48);var anchor=install(h,DreamseekersMod.DREAM_ANCHOR,pos(h,8,1,8),account("Deposit"),true);var delivery=worker(h,"Deposit",6,1,12);var pickup=worker(h,"Pickup",35,1,12);ItemEntity[] token={null};int value=ResourceSources.getFromItem(Items.OAK_LOG).resourceValue;long[] castAt={0};
        ready(h,delivery,pickup).thenExecute(()->{BlockPos approach=FlightWorkPositions.building(delivery,anchor);h.assertTrue(approach!=null,"real native stockpile supplies a clear reachable work face");Vec3 p=FlightWorkPositions.feet(approach);delivery.moveTo(p.x,p.y,p.z);h.assertTrue(FlightWorkPositions.canWorkAtBuilding(delivery,anchor,approach)&&anchor.getBuilding().canAcceptResources,"declared at-stockpile geometry is really usable, not a fake deposit call");delivery.getItems().add(new ItemStack(Items.OAK_LOG,1));h.assertTrue(Resources.getTotalResourcesFromItems(delivery.getItems()).wood==value,"explicit declared valued cargo is tracked, never silently erased");delivery.setNoAi(false);pickup.setNoAi(false);require(h,cast(h,delivery),SkillResult.SUCCESS,"at-stockpile personal activation before any deposit order");require(h,cast(h,pickup),SkillResult.SUCCESS,"idle resource pickup pause");castAt[0]=h.getLevel().getGameTime();order(h,delivery,UnitAction.RETURN_RESOURCES,anchor.originPos);var item=new ItemEntity(h.getLevel(),pickup.getX()+.35,pickup.getY(),pickup.getZ(),new ItemStack(Items.OAK_LOG,2));item.setNoPickUpDelay();item.setNoGravity(true);item.setDeltaMovement(Vec3.ZERO);token[0]=item;ENTITIES.add(item);h.assertTrue(h.getLevel().addFreshEntity(item),"real nonfood valued world drop is published");})
          .thenWaitUntil(()->h.assertTrue(delivery.getReturnResourcesGoal().getBuildingTarget()==anchor&&!UnitServerEvents.hasPendingImmediateAction(delivery.getId()),"new RETURN accepted during rush updates current native target"))
          .thenWaitUntil(()->h.assertTrue(h.getLevel().getGameTime()-castAt[0]==99,"exact original ninety-nine tick pause"))
          .thenExecute(()->{h.assertTrue(FireflyRush.active(delivery)&&!delivery.getReturnResourcesGoal().canDropOff()&&Resources.getTotalResourcesFromItems(delivery.getItems()).wood==value,"physically at-stockpile worker cannot transfer its real cargo during rush");h.assertTrue(!token[0].isRemoved()&&token[0].getItem().getCount()==2&&pickup.getItems().isEmpty(),"real RoN valued pickup is blocked before threshold/autoreturn, not merely hidden from UI");stableBank(h,"Deposit");stableBank(h,"Pickup");})
          .thenWaitUntil(()->h.assertTrue(bank(h,"Deposit").wood==5000+value&&delivery.getItems().isEmpty()&&Resources.getTotalResourcesFromItems(pickup.getItems()).wood==2*value,"natural expiry permits one real native deposit and one real valued pickup"))
          .thenIdle(25).thenExecute(()->{h.assertTrue(bank(h,"Deposit").wood==5000+value&&delivery.getItems().isEmpty()&&Resources.getTotalResourcesFromItems(pickup.getItems()).wood==2*value&&token[0].isRemoved(),"continued ticks do not duplicate bank credit or carried dropped resources");unchangedOtherResources(h,"Deposit");stableBank(h,"Pickup");pass("AT_STOCKPILE_DEPOSIT_PICKUP_PAUSE_EXACT_LEDGER");}).thenSucceed();
    }

    @GameTest(template="work_isolation_arena",batch=BATCH,timeoutTicks=1600)
    public static void newMoveStopGatherAndShiftUseCurrentOrdersWithoutCancelingRush(GameTestHelper h){
        arena(h,72,16,48);var moving=worker(h,"Orders",5,1,6);var stopped=worker(h,"Orders",5,1,14);var changed=worker(h,"Orders",5,1,22);var queued=worker(h,"Orders",5,1,30);var idle=worker(h,"Orders",40,1,38);FireflyWorker[] jobs={moving,stopped,changed,queued};BlockPos[] logs=new BlockPos[4];for(int i=0;i<4;i++){logs[i]=pos(h,11,2,6+i*8);h.getLevel().setBlock(logs[i],Blocks.OAK_LOG.defaultBlockState(),3);}BlockPos newLog=pos(h,8,2,23);h.getLevel().setBlock(newLog,Blocks.OAK_LOG.defaultBlockState(),3);Vec3[] beginnings=new Vec3[3];long[] time={0};int[] newProgress={0};int[] diagnosticBucket={Integer.MIN_VALUE};
        ready(h,moving,stopped,changed,queued,idle).thenExecute(()->{for(int i=0;i<jobs.length;i++){jobs[i].setNoAi(false);order(h,jobs[i],UnitAction.MOVE,logs[i]);}idle.setNoAi(false);ordersDiagnostic(h,"initial_work_wait",time[0],moving,stopped,changed,queued,idle);})
          .thenWaitUntil(()->{for(int i=0;i<jobs.length;i++)h.assertTrue(logs[i].equals(jobs[i].getGatherResourceGoal().getGatherTarget())&&!jobs[i].getNavigation().isDone(),"actual current work path is running before pause: "+i);})
          .thenExecute(()->{ordersDiagnostic(h,"work_ready_before_cast",time[0],moving,stopped,changed,queued,idle);for(var w:jobs)w.getNavigation().recomputePath();for(var w:jobs)require(h,cast(h,w),SkillResult.SUCCESS,"pause genuine work route including native path recompute");require(h,cast(h,idle),SkillResult.SUCCESS,"idle rush");time[0]=h.getLevel().getGameTime();beginnings[0]=moving.position();beginnings[1]=stopped.position();beginnings[2]=idle.position();order(h,moving,UnitAction.MOVE,pos(h,24,0,6));order(h,stopped,UnitAction.STOP,BlockPos.ZERO);order(h,changed,UnitAction.MOVE,newLog);order(h,queued,UnitAction.MOVE,pos(h,24,0,30),true);order(h,idle,UnitAction.MOVE,pos(h,55,0,38),true);ordersDiagnostic(h,"cast_and_new_orders_submitted",time[0],moving,stopped,changed,queued,idle);})
          .thenWaitUntil(()->{ordersWaitingDiagnostic(h,"new_order_wait",time[0],diagnosticBucket,moving,stopped,changed,queued,idle);h.assertTrue(!UnitServerEvents.hasPendingImmediateAction(changed.getId())&&newLog.equals(changed.getGatherResourceGoal().getGatherTarget()),"new authenticated gather target replaces old during unchanged speed interval");movedOrder(h,moving);movedOrder(h,idle);h.assertTrue(stopped.getGatherResourceGoal().getTargetResourceName()==ResourceName.NONE,"STOP truly clears old work");})
          .thenExecute(()->{newProgress[0]=changed.getGatherResourceGoal().getGatherTicksLeft();ordersDiagnostic(h,"new_order_wait_passed_before_exact99",time[0],moving,stopped,changed,queued,idle);diagnosticBucket[0]=Integer.MIN_VALUE;})
          .thenWaitUntil(()->{ordersWaitingDiagnostic(h,"exact99_wait",time[0],diagnosticBucket,moving,stopped,changed,queued,idle);h.assertTrue(h.getLevel().getGameTime()-time[0]==99,"observe original rush lifetime, not a restarted command-relative clock");})
          .thenExecute(()->{ordersDiagnostic(h,"exact99_reached",time[0],moving,stopped,changed,queued,idle);for(var w:jobs)h.assertTrue(FireflyRush.remainingTicks(w)==1,"new commands never cancel or refresh personal speed");h.assertTrue(moving.position().distanceTo(beginnings[0])>1&&idle.position().distanceTo(beginnings[2])>1,"new MOVE and idle-rush Shift MOVE actually travel during rush");h.assertTrue(stopped.position().distanceToSqr(beginnings[1])<.04&&stopped.getMoveGoal().getMoveTarget()==null,"STOP does not leave a previous work repath alive");h.assertTrue(newLog.equals(changed.getGatherResourceGoal().getGatherTarget())&&changed.getGatherResourceGoal().getGatherTicksLeft()==newProgress[0]&&changed.getNavigation().isDone()&&h.getLevel().getBlockState(newLog).is(Blocks.OAK_LOG),"new gather current intent is accepted but progress and work navigation wait for original expiry");h.assertTrue(logs[3].equals(queued.getGatherResourceGoal().getGatherTarget())&&UnitServerEvents.getUnitActionSlowQueue().stream().anyMatch(q->Arrays.stream(q.getUnitIds()).anyMatch(id->id==queued.getId())),"genuinely paused work remains nonidle so authenticated Shift queue does not dispatch early");for(BlockPos log:logs)h.assertTrue(h.getLevel().getBlockState(log).is(Blocks.OAK_LOG),"no old paused job harvested while speed active");stableBank(h,"Orders");})
          .thenIdle(45).thenExecute(()->{ordersDiagnostic(h,"post45_observation",time[0],moving,stopped,changed,queued,idle);h.assertTrue(!FireflyRush.active(stopped)&&stopped.getGatherResourceGoal().getTargetResourceName()==ResourceName.NONE&&stopped.getMoveGoal().getMoveTarget()==null&&stopped.position().distanceToSqr(beginnings[1])<.04,"expiry cannot restore STOP-replaced snapshot");h.assertTrue(moving.getGatherResourceGoal().getTargetResourceName()==ResourceName.NONE&&h.getLevel().getBlockState(logs[0]).is(Blocks.OAK_LOG),"expiry cannot restore MOVE-replaced old work");h.assertTrue(changed.getGatherResourceGoal().getGatherTicksLeft()<newProgress[0]||!h.getLevel().getBlockState(newLog).is(Blocks.OAK_LOG),"only currently selected new gather resumes naturally");pass("NEW_COMMANDS_CURRENT_INTENT_SHIFT_NO_STALE_RESTORE");}).thenSucceed();
    }

    @GameTest(template="unit_isolation_arena",batch=BATCH,timeoutTicks=1000)
    public static void ownerAbaDeathUnloadAndNativeNbtClearOnlyShortEffectNotSpentCooldown(GameTestHelper h){
        arena(h,24,8,24);var aba=worker(h,"LifeA",4,1,4);var dead=worker(h,"LifeD",4,1,10);var unloaded=worker(h,"LifeU",4,1,16);var saved=worker(h,"LifeN",10,1,4);var reserveD=worker(h,"LifeD",19,1,10);var reserveU=worker(h,"LifeU",19,1,16);var reserveN=worker(h,"LifeN",19,1,4);FireflyWorker[] loaded={null};double[] baseline={0};
        ready(h,aba,dead,unloaded,saved,reserveD,reserveU,reserveN).thenExecute(()->{saved.getAttribute(Attributes.FLYING_SPEED).addPermanentModifier(new AttributeModifier(PERMANENT_FLY,"persistent native flight technology fixture",.025,AttributeModifier.Operation.ADDITION));baseline[0]=saved.getAttributeValue(Attributes.FLYING_SPEED);for(var w:new FireflyWorker[]{aba,dead,unloaded,saved})require(h,cast(h,w),SkillResult.SUCCESS,"actual live owned worker activation before lifecycle transition");String old=aba.getOwnerName();aba.setOwnerName(account("LifeB"));aba.setOwnerName(old);h.assertTrue(!FireflyRush.active(aba)&&cd(aba)==500,"same-tick owner ABA immediately revokes rush without refund");close(h,SkillEffects.bonus(aba,BuffKind.MOVEMENT_SPEED),0,"owner revision removes actual speed contribution");dead.hurt(dead.damageSources().genericKill(),10000);h.assertTrue(!dead.isAlive()&&!FireflyRush.active(dead)&&cd(dead)==500,"real death clears short state but not original paid cooldown");unloaded.remove(Entity.RemovalReason.UNLOADED_TO_CHUNK);h.assertTrue(!FireflyRush.active(unloaded)&&cd(unloaded)==500,"real unload immediately revokes short authority without refund");CompoundTag tag=saved.saveWithoutId(new CompoundTag());UUID uuid=saved.getUUID();saved.remove(Entity.RemovalReason.UNLOADED_TO_CHUNK);var copy=DreamseekersMod.FIREFLY_WORKER.get().create(h.getLevel());copy.load(tag);loaded[0]=copy;ENTITIES.add(copy);h.assertTrue(copy.getUUID().equals(uuid)&&!FireflyRush.active(copy)&&cd(copy)==500,"native same-process NBT load has no transient rush and preserves absolute spent cooldown (not a two-JVM claim)");h.assertTrue(h.getLevel().addFreshEntity(copy),"actual reloaded identity publishes after original was removed");})
          .thenWaitUntil(()->h.assertTrue(loaded[0].tickCount>3&&h.getLevel().getEntity(loaded[0].getUUID())==loaded[0]&&h.getLevel().getEntity(loaded[0].getId())==loaded[0],"normally loaded object has actual published identity"))
          .thenIdle(5).thenExecute(()->{h.assertTrue(!FireflyRush.active(loaded[0])&&cd(loaded[0])>0&&cd(loaded[0])<500,"natural post-load ticks never replay rush or refund cooldown");close(h,loaded[0].getAttributeValue(Attributes.FLYING_SPEED),baseline[0],"permanent native attribute survives save/load while short modifier does not");h.assertTrue(loaded[0].getAttribute(Attributes.FLYING_SPEED).getModifier(PERMANENT_FLY)!=null,"exact permanent modifier survives");for(String owner:new String[]{"LifeA","LifeD","LifeU","LifeN"})stableBank(h,owner);pass("OWNER_ABA_DEATH_UNLOAD_NATIVE_NBT_NO_REPLAY");}).thenSucceed();
    }

    @GameTest(template="unit_isolation_arena",batch=BATCH,timeoutTicks=1000)
    public static void genuinelyIdleWorkerCompletesShortMoveThenDispatchesQueuedNextLegDuringRush(GameTestHelper h){
        arena(h,24,8,24);var w=worker(h,"ShortQueue",5,1,10);BlockPos first=pos(h,7,0,10),second=pos(h,15,0,10);Vec3[] start={null},completed={null};long[] castAt={0},firstAt={0};
        ready(h,w).thenExecute(()->w.setNoAi(false))
          .thenWaitUntil(()->h.assertTrue(w.getGatherResourceGoal().isIdle()&&w.isIdle()&&w.getGatherResourceGoal().getTargetResourceName()==ResourceName.NONE&&w.getMoveGoal().getMoveTarget()==null&&w.getNavigation().isDone(),"genuine native idle counter transitions naturally before activation; no test setter/forced idle"))
          .thenExecute(()->{start[0]=w.position();require(h,cast(h,w),SkillResult.SUCCESS,"genuinely idle source begins unchanged hundred-tick rush");castAt[0]=h.getLevel().getGameTime();h.assertTrue(!FireflyRush.hasPausedWork(w),"fixture has no old work to pause");order(h,w,UnitAction.MOVE,first);order(h,w,UnitAction.MOVE,second,true);System.out.println("FIREFLY_RUSH_SHORT_QUEUE_CAST time="+castAt[0]+" first="+first+" second="+second+" "+rawRushState(w));})
          .thenWaitUntil(()->h.assertTrue(!UnitServerEvents.hasPendingImmediateAction(w.getId())&&first.above().equals(w.getMoveGoal().getMoveTarget())&&!w.getNavigation().isDone(),"first real short MOVE was dispatched, not skipped by an early Shift leg"))
          .thenWaitUntil(()->h.assertTrue(w.position().distanceTo(Vec3.atBottomCenterOf(first.above()))<1&&(w.getMoveGoal().getMoveTarget()==null||second.above().equals(w.getMoveGoal().getMoveTarget())),"actual first flight leg reaches its destination and its first MOVE target completes"))
          .thenExecute(()->{firstAt[0]=h.getLevel().getGameTime();completed[0]=w.position();boolean alreadySecond=second.above().equals(w.getMoveGoal().getMoveTarget());if(alreadySecond){var live=w.getNavigation().getPath();h.assertTrue(live!=null&&!w.getNavigation().isDone()&&live.getTarget().equals(second.above())&&UnitServerEvents.getUnitActionSlowQueue().stream().noneMatch(q->Arrays.stream(q.getUnitIds()).anyMatch(id->id==w.getId())),"if same-tick native dispatch already occurred it must be the exact real second order, never spawn drift");}else h.assertTrue(w.getDeltaMovement().lengthSqr()<1.0e-10,"first leg naturally stopped before the second-leg observation; never clear velocity in fixture");h.assertTrue(firstAt[0]-castAt[0]<60&&w.position().distanceTo(start[0])>.75&&FireflyRush.active(w),"real two-block first leg finishes early enough that a subsequent twenty-tick test stays inside original rush");System.out.println("FIREFLY_RUSH_SHORT_QUEUE_FIRST_COMPLETE elapsed="+(firstAt[0]-castAt[0])+" queued="+UnitServerEvents.getUnitActionSlowQueue().stream().filter(q->Arrays.stream(q.getUnitIds()).anyMatch(id->id==w.getId())).count()+" "+rawRushState(w));})
          .thenIdle(20).thenExecute(()->{System.out.println("FIREFLY_RUSH_SHORT_QUEUE_SECOND_OBSERVATION elapsed="+(h.getLevel().getGameTime()-castAt[0])+" movedAfterFirst="+w.position().distanceTo(completed[0])+" queued="+UnitServerEvents.getUnitActionSlowQueue().stream().filter(q->Arrays.stream(q.getUnitIds()).anyMatch(id->id==w.getId())).count()+" "+rawRushState(w));h.assertTrue(FireflyRush.active(w)&&FireflyRush.remainingTicks(w)==100-(h.getLevel().getGameTime()-castAt[0]),"second-leg observation still uses original active duration, not expiry or a refreshed cast");var secondPoint=Vec3.atBottomCenterOf(second.above());var toward=secondPoint.subtract(completed[0]).multiply(1,0,1);var horizontal=w.position().subtract(completed[0]).multiply(1,0,1);double forward=horizontal.dot(toward.normalize()),remaining=secondPoint.subtract(w.position()).horizontalDistance(),forwardVelocity=w.getDeltaMovement().dot(toward.normalize());var livePath=w.getNavigation().getPath();System.out.println("FIREFLY_RUSH_SHORT_QUEUE_HORIZONTAL_PROOF forward="+forward+" initialRemaining="+toward.length()+" remaining="+remaining+" forwardVelocity="+forwardVelocity);h.assertTrue(second.above().equals(w.getMoveGoal().getMoveTarget())&&!w.getNavigation().isDone()&&livePath!=null&&livePath.getTarget().equals(second.above())&&forward>1.0e-6&&remaining<toward.length()-1.0e-6&&forwardVelocity>1.0e-6&&UnitServerEvents.getUnitActionSlowQueue().stream().noneMatch(q->Arrays.stream(q.getUnitIds()).anyMatch(id->id==w.getId())),"native no-work transition must dispatch the exact queued second path and make genuine horizontal progress toward it within original twenty ticks; noise tolerance is not a speed quota");h.assertTrue(w.getGatherResourceGoal().getTargetResourceName()==ResourceName.NONE&&w.getItems().isEmpty(),"no gather/work or cargo was fabricated to unblock queue");stableBank(h,"ShortQueue");pass("TRUE_IDLE_SHORT_MOVE_SHIFT_NEXT_LEG_DURING_RUSH");}).thenSucceed();
    }

    private static void idleDriftMatch(GameTestHelper h,FireflyWorker boosted,FireflyWorker control,Vec3[] start,String why){Vec3 a=boosted.position().subtract(start[0]),b=control.position().subtract(start[1]);h.assertTrue(a.distanceToSqr(b)<1.0e-10,why+": rushDelta="+a+" uncastDelta="+b);for(var w:new FireflyWorker[]{boosted,control})h.assertTrue(w.getMoveGoal().getMoveTarget()==null&&w.getNavigation().isDone()&&w.getNavigation().getPath()==null&&w.getReturnResourcesGoal().getBuildingTarget()==null&&w.getGatherResourceGoal().getTargetResourceName()==ResourceName.NONE&&w.getFollowTarget()==null,"both real idle entities have no navigation, home, follow or work target");h.assertTrue(!FireflyRush.active(control)&&cd(control)==0,"matched native inertia control truly never cast or paid a cooldown");}

    /** Read-only, first/edge/200-tick diagnostics; never registers callbacks or advances a goal. */
    private static void ordersWaitingDiagnostic(GameTestHelper h,String phase,long start,int[] last,FireflyWorker...workers){long elapsed=h.getLevel().getGameTime()-start;int bucket=elapsed>=98&&elapsed<=102?(int)elapsed:1000+(int)(elapsed/200);if(bucket!=last[0]){last[0]=bucket;ordersDiagnostic(h,phase,start,workers);}}
    private static void ordersDiagnostic(GameTestHelper h,String phase,long start,FireflyWorker...workers){System.out.println("FIREFLY_RUSH_ORDERS_DIAGNOSTIC phase="+phase+" gameTime="+h.getLevel().getGameTime()+" testTick="+h.getTick()+" elapsed="+(h.getLevel().getGameTime()-start));for(var w:workers)System.out.println("FIREFLY_RUSH_ORDERS_WORKER id="+w.getId()+" tick="+w.tickCount+" active="+FireflyRush.active(w)+" remaining="+FireflyRush.remainingTicks(w)+" gatherIdle="+w.getGatherResourceGoal().isIdle()+" pausedWork="+FireflyRush.hasPausedWork(w)+" pending="+UnitServerEvents.hasPendingImmediateAction(w.getId())+" queued="+UnitServerEvents.getUnitActionSlowQueue().stream().filter(q->Arrays.stream(q.getUnitIds()).anyMatch(id->id==w.getId())).map(q->q.getAction().toString()).toList()+" "+rawRushState(w));}
    /** No isGathering/isIdle(Unit)/canDropOff: those native probes may plan/cache an approach. */
    private static String rawRushState(FireflyWorker w){var path=w.getNavigation().getPath();return "pos="+w.position()+" velocity="+w.getDeltaMovement()+" move="+w.getMoveGoal().getMoveTarget()+" navDone="+w.getNavigation().isDone()+" path="+(path==null?"null":path.getNextNodeIndex()+"/"+path.getNodeCount()+"@"+path.getTarget())+" control="+w.getMoveControl().operation+" gather="+w.getGatherResourceGoal().getGatherTarget()+" gatherMove="+w.getGatherResourceGoal().getMoveTarget()+" gatherName="+w.getGatherResourceGoal().getTargetResourceName()+" gatherLeft="+w.getGatherResourceGoal().getGatherTicksLeft()+" gatherIdle="+w.getGatherResourceGoal().isIdle()+" return="+(w.getReturnResourcesGoal().getBuildingTarget()==null?"null":w.getReturnResourcesGoal().getBuildingTarget().originPos)+" build="+(w.getBuildRepairGoal().getBuildingTarget()==null?"null":w.getBuildRepairGoal().getBuildingTarget().originPos)+" follow="+(w.getFollowTarget()==null?"null":w.getFollowTarget().getUUID());}
    private static final Set<net.minecraft.world.level.ChunkPos> FORCED=new HashSet<>();
    private static void arena(GameTestHelper h,int width,int height,int depth){var level=h.getLevel();BlockPos p=pos(h,0,0,0);for(int cx=p.getX()>>4;cx<=(p.getX()+width-1)>>4;cx++)for(int cz=p.getZ()>>4;cz<=(p.getZ()+depth-1)>>4;cz++){var chunk=new net.minecraft.world.level.ChunkPos(cx,cz);if(!level.getForcedChunks().contains(chunk.toLong())){FORCED.add(chunk);level.setChunkForced(cx,cz,true);}}for(int x=0;x<width;x++)for(int z=0;z<depth;z++)level.setBlock(p.offset(x,height-1,z),Blocks.STONE.defaultBlockState(),2);level.getEntitiesOfClass(net.minecraft.world.entity.item.FallingBlockEntity.class,new AABB(p.getX(),p.getY()+1,p.getZ(),p.getX()+width,level.getMaxBuildHeight(),p.getZ()+depth)).forEach(Entity::discard);for(int x=0;x<width;x++)for(int z=0;z<depth;z++){level.setBlock(p.offset(x,0,z),Blocks.STONE.defaultBlockState(),2);for(int y=1;y<height-1;y++)level.setBlock(p.offset(x,y,z),(x==0||x==width-1||z==0||z==depth-1?Blocks.STONE:Blocks.AIR).defaultBlockState(),2);}level.getEntitiesOfClass(ItemEntity.class,new AABB(p,p.offset(width,height,depth))).forEach(Entity::discard);}
    private static BuildingPlacement install(GameTestHelper h,Building building,BlockPos p,String owner,boolean complete){var blocks=BuildingUtils.getAbsoluteBlockData(building.getRelativeBlockData(h.getLevel()),h.getLevel(),p,Rotation.NONE);int low=blocks.stream().mapToInt(b->b.getBlockPos().getY()).min().orElseThrow();for(var block:blocks)if(complete||block.getBlockPos().getY()<low+building.foundationYLayers&&building.startingBlockTypes.contains(block.getBlockState().getBlock()))h.getLevel().setBlock(block.getBlockPos(),block.getBlockState(),2);var placement=BuildingUtils.getNewBuildingPlacement(building,h.getLevel(),p,Rotation.NONE,owner,false);BuildingServerEvents.getBuildings().add(placement);if(complete)placement.onBuilt();placement.initPlacedBlocks();h.assertTrue(complete?placement.isBuilt:!placement.isBuilt&&placement.getBlocksPlaced()>0,"declared geometry fixture: full existing building or native unfinished foundation; no worker progress is fabricated");return placement;}
    private static String account(String suffix){String name=suffix.startsWith(PREFIX)?suffix:PREFIX+suffix;if(ACCOUNTS.add(name)){PlayerServerEvents.rtsPlayers.add(RTSPlayer.getNewBot(name,DreamseekersMod.DREAMSEEKERS));ResourcesServerEvents.resourcesList.add(new Resources(name,5000,5000,5000,5000));}return name;}
    private static Resources bank(GameTestHelper h,String suffix){String name=suffix.startsWith(PREFIX)?suffix:PREFIX+suffix;var result=ResourcesServerEvents.resourcesList.stream().filter(r->r.ownerName.equals(name)).findFirst().orElse(null);h.assertTrue(result!=null,"real owner ledger stays present; no recreation/fallback: "+name);return result;}
    private static void pending(GameTestHelper h,Resources r){h.assertTrue(r.foodToAdd==0&&r.woodToAdd==0&&r.oreToAdd==0&&r.emeraldToAdd==0,"all four exact pending balances remain zero: "+r.ownerName);}
    private static void stableBank(GameTestHelper h,String owner){var r=bank(h,owner);h.assertTrue(r.food==5000&&r.wood==5000&&r.ore==5000&&r.emerald==5000,"skill/commands alone do not spend or mint global resources: "+r.ownerName+" "+r.food+"/"+r.wood+"/"+r.ore+"/"+r.emerald);pending(h,r);}
    private static void unchangedOtherResources(GameTestHelper h,String owner){var r=bank(h,owner);h.assertTrue(r.food==5000&&r.ore==5000&&r.emerald==5000,"real wood-only work leaves other resource banks unchanged");pending(h,r);}
    private static FireflyWorker worker(GameTestHelper h,String owner,int x,int y,int z){var w=DreamseekersMod.FIREFLY_WORKER.get().create(h.getLevel());h.assertTrue(w!=null,"actual firefly factory exists");w.setOwnerName(account(owner));w.setNoAi(true);w.getAttribute(AttributeRegistrar.AGGRO_RANGE.get()).setBaseValue(0);place(h,w,x,y,z);player(h,owner);return w;}
    private static void place(GameTestHelper h,Entity e,int x,int y,int z){BlockPos p=pos(h,x,y,z);e.moveTo(p.getX()+.5,p.getY(),p.getZ()+.5);ENTITIES.add(e);h.assertTrue(h.getLevel().addFreshEntity(e),"actual fixture world accepts entity");}
    private static BlockPos pos(GameTestHelper h,int x,int y,int z){return h.absolutePos(new BlockPos(x,y,z));}
    private static FakePlayer player(GameTestHelper h,String suffix){String name=account(suffix);return PLAYERS.computeIfAbsent(name,key->{var p=new FakePlayer(h.getLevel(),new GameProfile(UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)),key));p.connection=new SilentHandler(p);var at=pos(h,2,1,21);p.moveTo(at.getX()+.5,at.getY(),at.getZ()+.5);ENTITIES.add(p);h.getLevel().addNewPlayer(p);PlayerServerEvents.players.add(p);return p;});}
    private static GameTestSequence ready(GameTestHelper h,Entity... entities){return h.startSequence().thenWaitUntil(()->{for(Entity e:entities)h.assertTrue(e.tickCount>3&&h.getLevel().getEntity(e.getId())==e&&h.getLevel().getEntity(e.getUUID())==e,"real published object/UUID and natural ticks: "+e.getId()+" tick="+e.tickCount+" removed="+e.isRemoved());}).thenExecute(()->{h.assertTrue(!com.solegendary.reignofnether.fogofwar.FogOfWarServerEvents.isEnabled(),"work smoke uses original real fog-off environment");for(Entity e:entities)if(e instanceof Unit u){h.assertTrue(u.getItems().isEmpty(),"ready has no accidental construction drops in unit cargo: "+e.getUUID()+" "+u.getItems());stableBank(h,u.getOwnerName());}System.out.println("FIREFLY_RUSH_READY testTick="+h.getTick()+" entities="+Arrays.stream(entities).map(e->e.getId()+":"+e.tickCount).toList());});}
    private static SkillRequest request(FireflyWorker w){return new SkillRequest(UnitSkill.FIREFLY_RUSH,w.getId(),w.getUUID(),w.rts().skills().revision(),w.getId(),w.getUUID());}
    private static SkillResult cast(GameTestHelper h,FireflyWorker w){return SkillService.request(player(h,w.getOwnerName()),request(w));}
    private static int cd(FireflyWorker w){return w.rts().skills().cooldownTicks(UnitSkill.FIREFLY_RUSH);}
    private static void movedOrder(GameTestHelper h,FireflyWorker w){h.assertTrue(!UnitServerEvents.hasPendingImmediateAction(w.getId())&&w.getMoveGoal().getMoveTarget()!=null&&!w.getNavigation().isDone(),"real authenticated non-work MOVE executed with actual path: "+FireflyNavigationTestDiagnostics.describe(w,bank(h,w.getOwnerName())));}
    private static void order(GameTestHelper h,FireflyWorker w,UnitAction action,BlockPos target){order(h,w,action,target,false);}
    private static void order(GameTestHelper h,FireflyWorker w,UnitAction action,BlockPos target,boolean shift){var sender=player(h,w.getOwnerName());try{var connection=new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);connection.setListener(sender.connection);var ctor=net.minecraftforge.network.NetworkEvent.Context.class.getDeclaredConstructor(net.minecraft.network.Connection.class,net.minecraftforge.network.NetworkDirection.class,int.class);ctor.setAccessible(true);var context=ctor.newInstance(connection,net.minecraftforge.network.NetworkDirection.PLAY_TO_SERVER,-1);h.assertTrue(context.getSender()==sender,"real Forge authenticated sender matches owner");h.assertTrue(new com.solegendary.reignofnether.unit.packets.UnitActionServerboundPacket(w.getOwnerName(),action,-1,new int[]{w.getId()},target,action==UnitAction.BUILD_REPAIR||action==UnitAction.RETURN_RESOURCES?target:BlockPos.ZERO,shift).handle(()->context),"actual authenticated command accepted: "+action);}catch(ReflectiveOperationException error){throw new RuntimeException("exact existing Forge command context",error);}}
    private static void require(GameTestHelper h,SkillResult actual,SkillResult expected,String why){h.assertTrue(actual==expected,why+": expected="+expected+" actual="+actual);}
    private static void close(GameTestHelper h,double actual,double expected,String why){h.assertTrue(Double.isFinite(actual)&&Math.abs(actual-expected)<.0005,why+": expected="+expected+" actual="+actual);}
    private static void pass(String name){System.out.println("DREAMSEEKERS_FIREFLY_RUSH_PASS "+name);}
    private static final class SilentHandler extends ServerGamePacketListenerImpl{SilentHandler(ServerPlayer p){super(p.serverLevel().getServer(),new net.minecraft.network.Connection(net.minecraft.network.protocol.PacketFlow.SERVERBOUND),p);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){}}
}
